  "claims": [
    {
      "id": "c:1186240184",
      "kind": "correctness",
      "harm": "Statically linked glibc binaries break when dynamic NSS resolvers attempt to load mismatched host glibc shared libraries.",
      "quote": "How does this handle resolvers? eg, static glibc 2.33 applications break on systems with glibc 2.34...",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3765886609"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3765886609",
      "settled_by_quote": "Thanks, taken your release note additions in the next push."
    },
    {
      "id": "c:1205515413",
      "kind": "correctness",
      "harm": "Early static binary builds crash on startup on older host systems like Ubuntu 20.04 due to glibc early init assertion failures.",
      "quote": "bitcoind: dl-call-libc-early-init.c:37: _dl_call_libc_early_init: Assertion `sym != NULL' failed. Aborted (core dumped)",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:1206165485",
        "c:1206686389"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:1225889653",
      "settled_by_quote": "Pushed a number of changes, and rebased on master. Switched from glibc 2.35 to 2.36."
    },
    {
      "id": "rc:3628650155",
      "kind": "correctness",
      "harm": "ELF FORTIFY security check returns True even when fortification is disabled because static binaries pull in libc.a symbol definitions.",
      "quote": "I don't think switching from `binary.imported_symbols` to `binary.symbols` provides a valid FORTIFY check for static binaries any more.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3675743445"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3675743445",
      "settled_by_quote": "For now I've opted to just return True for any static bin; I'm not sure if a more involved approach is worthwhile, will think about it some more."
    },
    {
      "id": "r:4905671621",
      "kind": "correctness",
      "harm": "Static binary attempts to open Guix store locale paths inherited from the build environment, leaking store paths and risking nondeterminism.",
      "quote": "trying to open some locales from the guix build environment and apparently so from the inherited glibc version",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:5268059707"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5268059707",
      "settled_by_quote": "This is due to Guix appending `(string-append \"libc_cv_complocaledir=/run/current-system/locale/\",(version-major+minor version))` onto it's glibc configure flags. I've filtered this out"
    }
  ],
